        if rng.random()<0.2:
            s[i]=rng.choice('ACGU')
    start=''.join(s)
    try:
        res=RNA.inverse_fold(start, target)
        seq=res[0]
        fc=RNA.fold_compound(seq)
        mfe,_=fc.mfe()
        dist=RNA.bp_distance(target,mfe)
        return (dist,seq)
    except Exception:
        return (999,'')

if __name__=='__main__':
